#!/usr/bin/env python3
"""Capture immutable effective RSL-RL configuration evidence for one run."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import re
import stat
from pathlib import Path
from typing import Any

import yaml
from yaml.nodes import MappingNode, Node, ScalarNode, SequenceNode

from capture_run_identity import RunIdentityError, validate_run_identity


class EffectiveConfigError(ValueError):
    """Raised when effective training configuration evidence is unsafe."""


MAX_EFFECTIVE_CONFIG_BYTES = 16 * 1024 * 1024
DEFAULT_MAX_DIFF_ENTRIES = 10_000
SHA256_RE = re.compile(r"^[0-9a-f]{64}$")


def _canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def _sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _reject_symlink_components(path: Path, *, label: str) -> None:
    if not path.is_absolute():
        raise EffectiveConfigError(f"{label} must be absolute")
    current = Path(path.anchor)
    for component in path.parts[1:]:
        current /= component
        if current.is_symlink():
            raise EffectiveConfigError(
                f"{label} contains a symlinked path component: {current}"
            )


def _signature(value: os.stat_result) -> tuple[int, int, int, int]:
    return (value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns)


def _read_stable_bytes(
    path: Path,
    *,
    label: str,
    max_bytes: int,
) -> tuple[bytes, dict[str, Any]]:
    if isinstance(max_bytes, bool) or not isinstance(max_bytes, int) or max_bytes <= 0:
        raise EffectiveConfigError("max_bytes must be a positive integer")
    _reject_symlink_components(path, label=label)
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError as exc:
        raise EffectiveConfigError(f"{label} does not exist: {path}") from exc
    except OSError as exc:
        raise EffectiveConfigError(f"cannot open {label}: {exc}") from exc
    with os.fdopen(descriptor, "rb") as stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode):
            raise EffectiveConfigError(f"{label} must be a regular file")
        if before.st_size > max_bytes:
            raise EffectiveConfigError(f"{label} exceeds {max_bytes} bytes")
        content = stream.read(max_bytes + 1)
        after = os.fstat(stream.fileno())
    if len(content) > max_bytes:
        raise EffectiveConfigError(f"{label} exceeds {max_bytes} bytes")
    if _signature(before) != _signature(after) or len(content) != after.st_size:
        raise EffectiveConfigError(f"{label} changed while it was read")
    return content, {
        "path": str(path),
        "sha256": _sha256_bytes(content),
        "size_bytes": len(content),
    }


def _read_stable_utf8(path: Path, *, label: str) -> tuple[str, dict[str, Any]]:
    _reject_symlink_components(path, label=label)
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError as exc:
        raise EffectiveConfigError(f"{label} does not exist: {path}") from exc
    except OSError as exc:
        raise EffectiveConfigError(f"cannot open {label}: {exc}") from exc
    with os.fdopen(descriptor, "rb") as stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode):
            raise EffectiveConfigError(f"{label} must be a regular file")
        content = stream.read()
        after = os.fstat(stream.fileno())
    if _signature(before) != _signature(after) or len(content) != after.st_size:
        raise EffectiveConfigError(f"{label} changed while it was read")
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise EffectiveConfigError(f"{label} must be UTF-8") from exc
    return text, {
        "path": str(path),
        "sha256": _sha256_bytes(content),
        "size_bytes": len(content),
        "signature": _signature(after),
    }


def _verify_unchanged(path: Path, metadata: dict[str, Any], *, label: str) -> None:
    _reject_symlink_components(path, label=label)
    try:
        current = os.stat(path, follow_symlinks=False)
    except FileNotFoundError as exc:
        raise EffectiveConfigError(f"{label} disappeared after capture") from exc
    if not stat.S_ISREG(current.st_mode):
        raise EffectiveConfigError(f"{label} must remain a regular file")
    if _signature(current) != tuple(metadata["signature"]):
        raise EffectiveConfigError(f"{label} changed during paired capture")


def _scalar_value(node: ScalarNode, *, label: str) -> Any:
    tag = node.tag
    if tag == "tag:yaml.org,2002:null":
        return None
    if tag == "tag:yaml.org,2002:bool":
        value = node.value.casefold()
        if value in {"true", "yes", "on"}:
            return True
        if value in {"false", "no", "off"}:
            return False
        raise EffectiveConfigError(f"{label} contains an invalid YAML boolean")
    if tag in {"tag:yaml.org,2002:int", "tag:yaml.org,2002:float"}:
        value = yaml.safe_load(node.value)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise EffectiveConfigError(f"{label} contains an invalid YAML number")
        if isinstance(value, float) and not math.isfinite(value):
            raise EffectiveConfigError(f"{label} contains a non-finite value")
        return value
    return node.value


def _mapping_items(node: Node, *, label: str) -> dict[str, Node]:
    if not isinstance(node, MappingNode):
        raise EffectiveConfigError(f"{label} must be a YAML mapping")
    result: dict[str, Node] = {}
    for key_node, value_node in node.value:
        if not isinstance(key_node, ScalarNode):
            raise EffectiveConfigError(f"{label} contains a non-scalar key")
        key = _scalar_value(key_node, label=f"{label} key")
        if not isinstance(key, str) or not key:
            raise EffectiveConfigError(f"{label} contains an invalid key")
        if key in result:
            raise EffectiveConfigError(f"{label} contains duplicate key: {key}")
        result[key] = value_node
    return result


def _canonical_node(node: Node, *, label: str) -> dict[str, Any]:
    if isinstance(node, ScalarNode):
        value = _scalar_value(node, label=label)
        return {"kind": "scalar", "tag": node.tag, "value": value}
    if isinstance(node, SequenceNode):
        return {
            "kind": "sequence",
            "tag": node.tag,
            "items": [
                _canonical_node(item, label=f"{label}[{index}]")
                for index, item in enumerate(node.value)
            ],
        }
    if isinstance(node, MappingNode):
        items = _mapping_items(node, label=label)
        return {
            "kind": "mapping",
            "tag": node.tag,
            "items": {
                key: _canonical_node(items[key], label=f"{label}.{key}")
                for key in sorted(items)
            },
        }
    raise EffectiveConfigError(f"{label} contains an unsupported YAML node")


def _parse_yaml(text: str, *, label: str) -> tuple[MappingNode, dict[str, Any]]:
    try:
        root = yaml.compose(text)
    except yaml.YAMLError as exc:
        raise EffectiveConfigError(f"invalid {label} YAML: {exc}") from exc
    if not isinstance(root, MappingNode):
        raise EffectiveConfigError(f"{label} must contain a YAML mapping")
    return root, _canonical_node(root, label=label)


def _path_node(root: Node, path: tuple[str, ...], *, label: str) -> Node:
    current = root
    for component in path:
        items = _mapping_items(current, label=label)
        if component not in items:
            raise EffectiveConfigError(
                f"{label} is missing required path: {'.'.join(path)}"
            )
        current = items[component]
    return current


def _required_scalar(root: Node, path: tuple[str, ...], *, label: str) -> Any:
    node = _path_node(root, path, label=label)
    if not isinstance(node, ScalarNode):
        raise EffectiveConfigError(
            f"{label}.{'.'.join(path)} must be a scalar"
        )
    return _scalar_value(node, label=f"{label}.{'.'.join(path)}")


def _optional_scalar(root: Node, path: tuple[str, ...], *, label: str) -> Any:
    current = root
    for component in path:
        if not isinstance(current, MappingNode):
            return None
        items = _mapping_items(current, label=label)
        if component not in items:
            return None
        current = items[component]
    if not isinstance(current, ScalarNode):
        return None
    return _scalar_value(current, label=f"{label}.{'.'.join(path)}")


def _reward_inventory(rewards: Node) -> tuple[dict[str, Any], dict[str, Any]]:
    terms = _mapping_items(rewards, label="env.rewards")
    if not terms:
        raise EffectiveConfigError("env.rewards must contain at least one term")
    inventory: dict[str, Any] = {}
    weights: dict[str, Any] = {}
    for name in sorted(terms):
        term = terms[name]
        if isinstance(term, ScalarNode) and _scalar_value(
            term,
            label=f"env.rewards.{name}",
        ) is None:
            inventory[name] = {"enabled": False, "weight": None}
            weights[name] = None
            continue
        term_items = _mapping_items(term, label=f"env.rewards.{name}")
        weight_node = term_items.get("weight")
        if not isinstance(weight_node, ScalarNode):
            raise EffectiveConfigError(
                f"env.rewards.{name}.weight must be a scalar"
            )
        weight = _scalar_value(
            weight_node,
            label=f"env.rewards.{name}.weight",
        )
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise EffectiveConfigError(
                f"env.rewards.{name}.weight must be a finite number"
            )
        inventory[name] = {
            "enabled": True,
            "weight": weight,
            "config_fingerprint": _sha256_bytes(
                _canonical_json(
                    _canonical_node(term, label=f"env.rewards.{name}")
                ).encode("utf-8")
            ),
        }
        weights[name] = weight
    return inventory, weights


def _training_parameters(env_root: Node, agent_root: Node) -> dict[str, Any]:
    return {
        "device": _optional_scalar(agent_root, ("device",), label="agent config"),
        "experiment_name": _optional_scalar(
            agent_root,
            ("experiment_name",),
            label="agent config",
        ),
        "logger": _optional_scalar(agent_root, ("logger",), label="agent config"),
        "max_iterations": _optional_scalar(
            agent_root,
            ("max_iterations",),
            label="agent config",
        ),
        "num_envs": _optional_scalar(
            env_root,
            ("scene", "num_envs"),
            label="env config",
        ),
        "num_steps_per_env": _optional_scalar(
            agent_root,
            ("num_steps_per_env",),
            label="agent config",
        ),
        "resume": _optional_scalar(agent_root, ("resume",), label="agent config"),
        "run_name": _optional_scalar(agent_root, ("run_name",), label="agent config"),
    }


def _reject_json_constant(value: str) -> None:
    raise EffectiveConfigError(f"JSON contains non-finite value: {value}")


def load_run_identity(path: Path) -> dict[str, Any]:
    if not path.is_absolute():
        raise EffectiveConfigError("run identity path must be absolute")
    try:
        encoded, _ = _read_stable_bytes(
            path,
            label="run identity",
            max_bytes=4 * 1024 * 1024,
        )
        value = json.loads(
            encoded.decode("utf-8"),
            parse_constant=_reject_json_constant,
        )
    except UnicodeDecodeError as exc:
        raise EffectiveConfigError("run identity must be UTF-8") from exc
    except json.JSONDecodeError as exc:
        raise EffectiveConfigError(
            f"invalid run identity JSON at line {exc.lineno}: {exc.msg}"
        ) from exc
    try:
        validate_run_identity(value)
    except RunIdentityError as exc:
        raise EffectiveConfigError(str(exc)) from exc
    assert isinstance(value, dict)
    return value


def _command_contains_task(command: list[str], task: str) -> bool:
    for index, token in enumerate(command):
        if token == f"--task={task}":
            return True
        if token == "--task" and index + 1 < len(command):
            return command[index + 1] == task
    return False


def capture_effective_config(
    run_identity: dict[str, Any],
    log_directory: Path,
) -> dict[str, Any]:
    """Return deterministic evidence from one run's effective YAML dumps."""
    try:
        validate_run_identity(run_identity)
    except RunIdentityError as exc:
        raise EffectiveConfigError(str(exc)) from exc
    repository_root = Path(run_identity["source"]["repository_root"])
    if not _command_contains_task(
        run_identity["training"]["command"],
        run_identity["task"],
    ):
        raise EffectiveConfigError(
            "run_identity.training.command must contain the exact task"
        )
    _reject_symlink_components(repository_root, label="repository root")
    _reject_symlink_components(log_directory, label="log directory")
    if repository_root != repository_root.resolve():
        raise EffectiveConfigError("repository root must be a canonical path")
    if log_directory != log_directory.resolve():
        raise EffectiveConfigError("log directory must be a canonical path")
    if not log_directory.is_dir():
        raise EffectiveConfigError("log directory must be an existing directory")
    expected_log_root = repository_root / "logs" / "rsl_rl"
    try:
        relative_log_directory = log_directory.relative_to(expected_log_root)
    except ValueError as exc:
        raise EffectiveConfigError(
            "log directory must be below the run identity repository logs/rsl_rl"
        ) from exc
    if not relative_log_directory.parts:
        raise EffectiveConfigError("log directory must identify one training run")
    if run_identity["run_id"] != log_directory.name:
        raise EffectiveConfigError(
            "run_identity.run_id does not match the run log directory"
        )

    env_path = log_directory / "params" / "env.yaml"
    agent_path = log_directory / "params" / "agent.yaml"
    env_text, env_source = _read_stable_utf8(env_path, label="env config")
    agent_text, agent_source = _read_stable_utf8(agent_path, label="agent config")
    _verify_unchanged(env_path, env_source, label="env config")
    _verify_unchanged(agent_path, agent_source, label="agent config")

    env_root, env_canonical = _parse_yaml(env_text, label="env config")
    agent_root, agent_canonical = _parse_yaml(agent_text, label="agent config")
    rewards = _path_node(env_root, ("rewards",), label="env config")
    reward_inventory, reward_weights = _reward_inventory(rewards)

    env_seed = _required_scalar(env_root, ("seed",), label="env config")
    agent_seed = _required_scalar(agent_root, ("seed",), label="agent config")
    runner_class = _required_scalar(
        agent_root,
        ("class_name",),
        label="agent config",
    )
    algorithm_class = _required_scalar(
        agent_root,
        ("algorithm", "class_name"),
        label="agent config",
    )
    experiment_name = _required_scalar(
        agent_root,
        ("experiment_name",),
        label="agent config",
    )
    if env_seed != run_identity["seed"] or agent_seed != run_identity["seed"]:
        raise EffectiveConfigError(
            "effective env/agent seed does not match run_identity.seed"
        )
    if runner_class != run_identity["runner"]:
        raise EffectiveConfigError(
            "effective runner class does not match run_identity.runner"
        )
    if not isinstance(algorithm_class, str) or not algorithm_class:
        raise EffectiveConfigError("effective algorithm class must be a string")
    if experiment_name != log_directory.parent.name:
        raise EffectiveConfigError(
            "effective experiment_name does not match the run log directory"
        )

    env_fingerprint = _sha256_bytes(
        _canonical_json(env_canonical).encode("utf-8")
    )
    agent_fingerprint = _sha256_bytes(
        _canonical_json(agent_canonical).encode("utf-8")
    )
    reward_fingerprint = _sha256_bytes(
        _canonical_json(
            _canonical_node(rewards, label="env.rewards")
        ).encode("utf-8")
    )
    effective_fingerprint = _sha256_bytes(
        _canonical_json(
            {"agent": agent_fingerprint, "environment": env_fingerprint}
        ).encode("utf-8")
    )

    for source in (env_source, agent_source):
        source.pop("signature")
    evidence = {
        "version": 1,
        "task": run_identity["task"],
        "run_id": run_identity["run_id"],
        "host_id": run_identity["host_id"],
        "run_identity_sha256": run_identity["identity_sha256"],
        "log_directory": str(log_directory),
        "source_files": {
            "environment": {**env_source, "content_utf8": env_text},
            "agent": {**agent_source, "content_utf8": agent_text},
        },
        "resolved_identity": {
            "declared_algorithm": run_identity["algorithm"],
            "algorithm_class": algorithm_class,
            "runner_class": runner_class,
            "seed": agent_seed,
        },
        "training_parameters": _training_parameters(env_root, agent_root),
        "reward_terms": reward_inventory,
        "reward_weights": reward_weights,
        "fingerprints": {
            "agent": agent_fingerprint,
            "effective_config": effective_fingerprint,
            "environment": env_fingerprint,
            "reward": reward_fingerprint,
        },
    }

    if run_identity["version"] == 2:
        evidence["version"] = 2
        del evidence["run_identity_sha256"]
    return evidence


def _require_exact_keys(value: Any, expected: set[str], *, label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != expected:
        raise EffectiveConfigError(
            f"{label} must contain exactly: {', '.join(sorted(expected))}"
        )
    return value


def validate_effective_config_evidence(
    evidence: Any,
    run_identity: dict[str, Any],
) -> None:
    """Recompute and validate one captured effective-config artifact."""
    try:
        validate_run_identity(run_identity)
    except RunIdentityError as exc:
        raise EffectiveConfigError(str(exc)) from exc
    document = _require_exact_keys(
        evidence,
        {
            "fingerprints",
            "host_id",
            "log_directory",
            "resolved_identity",
            "reward_terms",
            "reward_weights",
            "run_id",
            "source_files",
            "task",
            "training_parameters",
            "version",
        }
        | ({"run_identity_sha256"} if evidence.get("version") == 1 else set()),
        label="effective config evidence",
    )
    if document["version"] not in {1, 2}:
        raise EffectiveConfigError("effective config evidence.version must be 1 or 2")
    expected_scope = {
        "task": run_identity["task"],
        "run_id": run_identity["run_id"],
        "host_id": run_identity["host_id"],
        "run_identity_sha256": run_identity["identity_sha256"],
    }
    if document["version"] == 2:
        if run_identity["version"] != 2:
            raise EffectiveConfigError("config v2 requires context v2")
        del expected_scope["run_identity_sha256"]
    for field, expected in expected_scope.items():
        if document[field] != expected:
            raise EffectiveConfigError(
                f"effective config evidence.{field} does not match run identity"
            )

    log_directory_value = document["log_directory"]
    if not isinstance(log_directory_value, str):
        raise EffectiveConfigError("effective config evidence.log_directory must be a string")
    log_directory = Path(log_directory_value)
    if not log_directory.is_absolute() or ".." in log_directory.parts:
        raise EffectiveConfigError("effective config evidence.log_directory must be absolute")
    repository_root = Path(run_identity["source"]["repository_root"])
    expected_log_root = repository_root / "logs" / "rsl_rl"
    try:
        relative_log_directory = log_directory.relative_to(expected_log_root)
    except ValueError as exc:
        raise EffectiveConfigError(
            "effective config evidence.log_directory is outside identity logs/rsl_rl"
        ) from exc
    if not relative_log_directory.parts or log_directory.name != run_identity["run_id"]:
        raise EffectiveConfigError(
            "effective config evidence.log_directory does not match run identity"
        )

    source_files = _require_exact_keys(
        document["source_files"],
        {"agent", "environment"},
        label="effective config evidence.source_files",
    )
    texts: dict[str, str] = {}
    expected_paths = {
        "environment": log_directory / "params" / "env.yaml",
        "agent": log_directory / "params" / "agent.yaml",
    }
    for name in ("environment", "agent"):
        source = _require_exact_keys(
            source_files[name],
            {"content_utf8", "path", "sha256", "size_bytes"},
            label=f"effective config evidence.source_files.{name}",
        )
        content = source["content_utf8"]
        if not isinstance(content, str):
            raise EffectiveConfigError(f"effective config {name} content must be UTF-8 text")
        encoded = content.encode("utf-8")
        if source["path"] != str(expected_paths[name]):
            raise EffectiveConfigError(f"effective config {name} source path mismatch")
        if source["size_bytes"] != len(encoded):
            raise EffectiveConfigError(f"effective config {name} source size mismatch")
        if source["sha256"] != _sha256_bytes(encoded):
            raise EffectiveConfigError(f"effective config {name} source SHA-256 mismatch")
        texts[name] = content

    env_root, env_canonical = _parse_yaml(texts["environment"], label="env config")
    agent_root, agent_canonical = _parse_yaml(texts["agent"], label="agent config")
    rewards = _path_node(env_root, ("rewards",), label="env config")
    reward_terms, reward_weights = _reward_inventory(rewards)
    env_seed = _required_scalar(env_root, ("seed",), label="env config")
    agent_seed = _required_scalar(agent_root, ("seed",), label="agent config")
    runner_class = _required_scalar(agent_root, ("class_name",), label="agent config")
    algorithm_class = _required_scalar(
        agent_root,
        ("algorithm", "class_name"),
        label="agent config",
    )
    experiment_name = _required_scalar(
        agent_root,
        ("experiment_name",),
        label="agent config",
    )
    if env_seed != run_identity["seed"] or agent_seed != run_identity["seed"]:
        raise EffectiveConfigError("effective config evidence seed mismatch")
    if runner_class != run_identity["runner"]:
        raise EffectiveConfigError("effective config evidence runner mismatch")
    if not isinstance(algorithm_class, str) or not algorithm_class:
        raise EffectiveConfigError("effective config evidence algorithm must be a string")
    if experiment_name != log_directory.parent.name:
        raise EffectiveConfigError("effective config evidence experiment mismatch")

    environment_fingerprint = _sha256_bytes(
        _canonical_json(env_canonical).encode("utf-8")
    )
    agent_fingerprint = _sha256_bytes(
        _canonical_json(agent_canonical).encode("utf-8")
    )
    reward_fingerprint = _sha256_bytes(
        _canonical_json(_canonical_node(rewards, label="env.rewards")).encode("utf-8")
    )
    effective_fingerprint = _sha256_bytes(
        _canonical_json(
            {"agent": agent_fingerprint, "environment": environment_fingerprint}
        ).encode("utf-8")
    )
    expected_values = {
        "fingerprints": {
            "agent": agent_fingerprint,
            "effective_config": effective_fingerprint,
            "environment": environment_fingerprint,
            "reward": reward_fingerprint,
        },
        "resolved_identity": {
            "declared_algorithm": run_identity["algorithm"],
            "algorithm_class": algorithm_class,
            "runner_class": runner_class,
            "seed": agent_seed,
        },
        "reward_terms": reward_terms,
        "reward_weights": reward_weights,
        "training_parameters": _training_parameters(env_root, agent_root),
    }
    for field, expected in expected_values.items():
        if document[field] != expected:
            raise EffectiveConfigError(f"effective config evidence.{field} mismatch")


def load_and_validate_effective_config(
    path: Path,
    *,
    expected_sha256: str,
    run_identity: dict[str, Any],
    max_bytes: int = MAX_EFFECTIVE_CONFIG_BYTES,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Read one immutable artifact, verify its hash, and recompute its contents."""
    if not isinstance(expected_sha256, str) or not SHA256_RE.fullmatch(expected_sha256):
        raise EffectiveConfigError("effective config expected SHA-256 is invalid")
    encoded, metadata = _read_stable_bytes(
        path,
        label="effective config evidence",
        max_bytes=max_bytes,
    )
    if metadata["sha256"] != expected_sha256:
        raise EffectiveConfigError("effective config evidence SHA-256 mismatch")
    try:
        value = json.loads(
            encoded.decode("utf-8"),
            parse_constant=_reject_json_constant,
        )
    except UnicodeDecodeError as exc:
        raise EffectiveConfigError("effective config evidence must be UTF-8") from exc
    except json.JSONDecodeError as exc:
        raise EffectiveConfigError(
            f"invalid effective config JSON at line {exc.lineno}: {exc.msg}"
        ) from exc
    validate_effective_config_evidence(value, run_identity)
    assert isinstance(value, dict)
    return value, metadata


def _json_pointer_component(value: str) -> str:
    return value.replace("~", "~0").replace("/", "~1")


def _flatten_yaml_node(node: Node, path: str, output: dict[str, dict[str, Any]]) -> None:
    if isinstance(node, ScalarNode):
        output[path] = _canonical_node(node, label=path or "root")
        return
    if isinstance(node, SequenceNode):
        output[path] = {"kind": "sequence", "tag": node.tag}
        for index, item in enumerate(node.value):
            _flatten_yaml_node(item, f"{path}/{index}", output)
        return
    if isinstance(node, MappingNode):
        output[path] = {"kind": "mapping", "tag": node.tag}
        items = _mapping_items(node, label=path or "root")
        for key in sorted(items):
            _flatten_yaml_node(
                items[key],
                f"{path}/{_json_pointer_component(key)}",
                output,
            )
        return
    raise EffectiveConfigError("effective config contains an unsupported YAML node")


def _mapping_changes(
    baseline: dict[str, Any],
    current: dict[str, Any],
) -> list[dict[str, Any]]:
    changes: list[dict[str, Any]] = []
    for key in sorted(set(baseline) | set(current)):
        if key not in baseline:
            change = "added"
            before = None
            after = current[key]
        elif key not in current:
            change = "removed"
            before = baseline[key]
            after = None
        elif baseline[key] != current[key]:
            change = "changed"
            before = baseline[key]
            after = current[key]
        else:
            continue
        changes.append(
            {"path": key, "change": change, "before": before, "after": after}
        )
    return changes


def compare_effective_configs(
    baseline: dict[str, Any],
    current: dict[str, Any],
    *,
    max_diff_entries: int = DEFAULT_MAX_DIFF_ENTRIES,
) -> dict[str, Any]:
    """Return a complete deterministic semantic diff of two validated artifacts."""
    if (
        isinstance(max_diff_entries, bool)
        or not isinstance(max_diff_entries, int)
        or max_diff_entries <= 0
    ):
        raise EffectiveConfigError("max_diff_entries must be a positive integer")
    flattened: dict[str, dict[str, dict[str, Any]]] = {}
    for label, evidence in (("baseline", baseline), ("current", current)):
        source_files = evidence.get("source_files")
        if not isinstance(source_files, dict):
            raise EffectiveConfigError(f"{label} effective config is not validated")
        values: dict[str, dict[str, Any]] = {}
        for scope, source_name in (("environment", "environment"), ("agent", "agent")):
            source = source_files.get(source_name)
            if not isinstance(source, dict) or not isinstance(source.get("content_utf8"), str):
                raise EffectiveConfigError(f"{label} effective config is not validated")
            root, _ = _parse_yaml(source["content_utf8"], label=f"{label} {scope}")
            _flatten_yaml_node(root, f"/{scope}", values)
        flattened[label] = values

    semantic_changes: list[dict[str, Any]] = []
    baseline_values = flattened["baseline"]
    current_values = flattened["current"]
    for path in sorted(set(baseline_values) | set(current_values)):
        if path not in baseline_values:
            change = "added"
            before = None
            after = current_values[path]
        elif path not in current_values:
            change = "removed"
            before = baseline_values[path]
            after = None
        elif baseline_values[path] != current_values[path]:
            change = "changed"
            before = baseline_values[path]
            after = current_values[path]
        else:
            continue
        semantic_changes.append(
            {"path": path, "change": change, "before": before, "after": after}
        )
    if len(semantic_changes) > max_diff_entries:
        raise EffectiveConfigError(
            f"effective config diff exceeds max-diff-entries={max_diff_entries}"
        )
    scope_counts = {"agent": 0, "environment": 0}
    for item in semantic_changes:
        scope = item["path"].split("/", 2)[1]
        scope_counts[scope] += 1
    return {
        "version": 1,
        "complete": True,
        "baseline": {
            "run_id": baseline["run_id"],
            "effective_config_fingerprint": baseline["fingerprints"]["effective_config"],
        },
        "current": {
            "run_id": current["run_id"],
            "effective_config_fingerprint": current["fingerprints"]["effective_config"],
        },
        "summary": {
            "semantic_changes": len(semantic_changes),
            "agent_changes": scope_counts["agent"],
            "environment_changes": scope_counts["environment"],
            "reward_weight_changes": len(
                _mapping_changes(baseline["reward_weights"], current["reward_weights"])
            ),
            "training_parameter_changes": len(
                _mapping_changes(
                    baseline["training_parameters"],
                    current["training_parameters"],
                )
            ),
        },
        "reward_weight_changes": _mapping_changes(
            baseline["reward_weights"],
            current["reward_weights"],
        ),
        "training_parameter_changes": _mapping_changes(
            baseline["training_parameters"],
            current["training_parameters"],
        ),
        "semantic_changes": semantic_changes,
    }


def write_new_evidence(path: Path, evidence: dict[str, Any]) -> dict[str, Any]:
    """Atomically publish one new effective-config evidence JSON."""
    if not path.is_absolute():
        raise EffectiveConfigError("--output must be a new absolute path")
    _reject_symlink_components(path.parent, label="--output")
    if not path.parent.is_dir():
        raise EffectiveConfigError("--output parent directory does not exist")
    if path.exists() or path.is_symlink():
        raise EffectiveConfigError("--output must be a new absolute path")
    encoded = json.dumps(
        evidence,
        indent=2,
        sort_keys=True,
        ensure_ascii=False,
        allow_nan=False,
    ) + "\n"
    temporary = path.parent / f".{path.name}.tmp-{os.getpid()}-{os.urandom(8).hex()}"
    try:
        with temporary.open("x", encoding="utf-8") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path, follow_symlinks=False)
        except FileExistsError as exc:
            raise EffectiveConfigError("--output must be a new absolute path") from exc
    finally:
        if temporary.exists():
            temporary.unlink()
    return {
        "version": 1,
        "effective_config_fingerprint": evidence["fingerprints"]["effective_config"],
        "evidence_path": str(path),
        "sha256": _sha256_bytes(encoded.encode("utf-8")),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("run_identity", help="Validated host-local run identity JSON")
    parser.add_argument("--log-dir", required=True, help="Absolute RSL-RL run directory")
    parser.add_argument("--output", help="Legacy v1 path; v2 chooses content-addressed storage")
    args = parser.parse_args()
    try:
        evidence = capture_effective_config(
            load_run_identity(Path(args.run_identity)),
            Path(args.log_dir),
        )
        if evidence["version"] == 2:
            from evidence_provenance import store_object, run_root
            if args.output:
                raise EffectiveConfigError("v2 config chooses its output; omit --output")
            receipt = store_object(run_root(load_run_identity(Path(args.run_identity))), "config", evidence)
        else:
            if not args.output:
                raise EffectiveConfigError("legacy config requires --output")
            receipt = write_new_evidence(Path(args.output), evidence)
    except (EffectiveConfigError, OSError) as exc:
        parser.error(str(exc))
    print(json.dumps(receipt, indent=2, sort_keys=True, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Capture deterministic local run identity without changing Git state."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import re
import subprocess
from pathlib import Path
from typing import Any


REPO_ROOT = Path(__file__).resolve().parents[4]
SAFE_IDENTIFIER_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")
HEAD_RE = re.compile(r"^[0-9a-f]{40}$")
SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
SCENARIO_FIELDS = {
    "scenario_id",
    "scenario_overrides",
    "command_schedule",
    "duration_steps",
    "num_envs",
    "seed",
}


class RunIdentityError(ValueError):
    """Raised when a run identity is incomplete, unsafe, or inconsistent."""


def _canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def _sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _validate_identifier(name: str, value: Any) -> None:
    if not isinstance(value, str) or not SAFE_IDENTIFIER_RE.fullmatch(value):
        raise RunIdentityError(f"{name} must be a safe ASCII identifier")


def _validate_string_array(name: str, value: Any, *, nonempty: bool) -> None:
    if (
        not isinstance(value, list)
        or (nonempty and not value)
        or any(not isinstance(item, str) or not item for item in value)
    ):
        requirement = "a non-empty" if nonempty else "an"
        raise RunIdentityError(f"{name} must be {requirement} array of non-empty strings")


def validate_scenario_contract(value: Any) -> None:
    if not isinstance(value, dict) or set(value) != SCENARIO_FIELDS:
        raise RunIdentityError(
            "evaluation scenario must contain exactly scenario_id, "
            "scenario_overrides, command_schedule, duration_steps, num_envs, and seed"
        )
    _validate_identifier("evaluation scenario_id", value["scenario_id"])
    if not isinstance(value["scenario_overrides"], dict):
        raise RunIdentityError("evaluation scenario_overrides must be an object")
    if not isinstance(value["command_schedule"], list):
        raise RunIdentityError("evaluation command_schedule must be an array")
    for field in ("duration_steps", "num_envs"):
        field_value = value[field]
        if isinstance(field_value, bool) or not isinstance(field_value, int) or field_value <= 0:
            raise RunIdentityError(f"evaluation {field} must be a positive integer")
    if isinstance(value["seed"], bool) or not isinstance(value["seed"], int):
        raise RunIdentityError("evaluation seed must be an integer")
    previous_end = -1
    for index, segment in enumerate(value["command_schedule"]):
        if not isinstance(segment, dict) or set(segment) != {
            "start_step",
            "end_step",
            "command",
        }:
            raise RunIdentityError(f"evaluation command schedule segment {index} is invalid")
        start = segment["start_step"]
        end = segment["end_step"]
        command = segment["command"]
        if (
            isinstance(start, bool)
            or not isinstance(start, int)
            or isinstance(end, bool)
            or not isinstance(end, int)
            or start != previous_end + 1
            or end < start
            or end >= value["duration_steps"]
        ):
            raise RunIdentityError(
                "evaluation command schedule must be ordered, contiguous, and within duration"
            )
        if (
            not isinstance(command, list)
            or len(command) != 3
            or any(
                isinstance(item, bool)
                or not isinstance(item, (int, float))
                or not math.isfinite(float(item))
                for item in command
            )
        ):
            raise RunIdentityError(
                "evaluation command schedule values must be finite [vx, vy, yaw_rate]"
            )
        previous_end = end
    if value["command_schedule"] and previous_end != value["duration_steps"] - 1:
        raise RunIdentityError(
            "evaluation command schedule must cover every evaluation step"
        )
    try:
        _canonical_json(value)
    except (TypeError, ValueError) as exc:
        raise RunIdentityError(f"evaluation scenario is not finite JSON: {exc}") from exc


def _reject_symlink_components(path: Path, *, label: str) -> None:
    if not path.is_absolute():
        raise RunIdentityError(f"{label} must be absolute")
    current = Path(path.anchor)
    for component in path.parts[1:]:
        current /= component
        if current.is_symlink():
            raise RunIdentityError(
                f"{label} contains a symlinked path component: {current}"
            )


def _safe_absolute_file(path: Path, *, label: str) -> Path:
    _reject_symlink_components(path, label=label)
    if not path.is_file():
        raise RunIdentityError(f"{label} is not a file: {path}")
    return path


def _repository_file(repo_root: Path, raw_path: str) -> tuple[Path, str]:
    candidate = Path(raw_path)
    if ".." in candidate.parts:
        raise RunIdentityError(f"config path cannot contain traversal: {raw_path}")
    if not candidate.is_absolute():
        candidate = repo_root / candidate
    candidate = _safe_absolute_file(candidate, label="config path")
    try:
        relative = candidate.relative_to(repo_root)
    except ValueError as exc:
        raise RunIdentityError(f"config path is outside repository: {candidate}") from exc
    if not relative.parts or relative.parts[0] == ".git":
        raise RunIdentityError(f"config path is not repository source: {candidate}")
    return candidate, relative.as_posix()


def _git_text(
    repo_root: Path,
    *args: str,
    allow_failure: bool = False,
) -> str:
    result = subprocess.run(
        ["git", "-c", "core.fsmonitor=false", "-C", str(repo_root), *args],
        check=False,
        capture_output=True,
        text=True,
        env={
            **os.environ,
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_TERMINAL_PROMPT": "0",
        },
    )
    if result.returncode != 0 and not allow_failure:
        raise RunIdentityError(
            f"local git {' '.join(args)} failed: {result.stderr.strip()}"
        )
    return result.stdout if result.returncode == 0 else ""


def _git_bytes(
    repo_root: Path,
    *args: str,
    allow_failure: bool = False,
) -> bytes | None:
    result = subprocess.run(
        ["git", "-c", "core.fsmonitor=false", "-C", str(repo_root), *args],
        check=False,
        capture_output=True,
        env={
            **os.environ,
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_TERMINAL_PROMPT": "0",
        },
    )
    if result.returncode != 0 and not allow_failure:
        raise RunIdentityError(
            f"local git {' '.join(args)} failed: "
            f"{result.stderr.decode('utf-8', errors='replace').strip()}"
        )
    return result.stdout if result.returncode == 0 else None


def _inspect_config_state(
    repo_root: Path,
    resolved_configs: list[tuple[Path, str]],
) -> tuple[list[str], list[str]]:
    dirty_paths: list[str] = []
    untracked_paths: list[str] = []
    for path, relative in resolved_configs:
        status = _git_text(
            repo_root,
            "status",
            "--porcelain=v1",
            "--untracked-files=all",
            "--",
            relative,
        )
        tracked = _git_text(
            repo_root,
            "ls-files",
            "--error-unmatch",
            "--",
            relative,
            allow_failure=True,
        )
        if not tracked:
            untracked_paths.append(relative)
            dirty_paths.append(relative)
            continue
        head_content = _git_bytes(
            repo_root,
            "show",
            f"HEAD:{relative}",
            allow_failure=True,
        )
        if status or head_content is None or path.read_bytes() != head_content:
            dirty_paths.append(relative)
    return sorted(set(dirty_paths)), sorted(set(untracked_paths))


def validate_run_identity(identity: Any) -> None:
    if not isinstance(identity, dict) or identity.get("version") not in {1, 2}:
        raise RunIdentityError("run_identity.version must be 1 or 2")
    for field in ("task", "run_id", "host_id", "backend", "algorithm", "runner"):
        _validate_identifier(f"run_identity.{field}", identity.get(field))
    seed = identity.get("seed")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise RunIdentityError("run_identity.seed must be an integer")

    source = identity.get("source")
    if not isinstance(source, dict):
        raise RunIdentityError("run_identity.source must be an object")
    repository_root = source.get("repository_root")
    if (
        not isinstance(repository_root, str)
        or not Path(repository_root).is_absolute()
        or ".." in Path(repository_root).parts
    ):
        raise RunIdentityError("run_identity.source.repository_root must be absolute")
    branch = source.get("branch")
    if not isinstance(branch, str) or not branch or len(branch) > 255:
        raise RunIdentityError("run_identity.source.branch must be a non-empty string")
    head = source.get("head")
    if not isinstance(head, str) or not HEAD_RE.fullmatch(head):
        raise RunIdentityError("run_identity.source.head must be a full lowercase commit")
    dirty = source.get("dirty")
    if not isinstance(dirty, bool):
        raise RunIdentityError("run_identity.source.dirty must be boolean")
    dirty_paths = source.get("dirty_paths")
    if (
        not isinstance(dirty_paths, list)
        or dirty_paths != sorted(set(dirty_paths))
        or any(
            not isinstance(path, str)
            or not path
            or Path(path).is_absolute()
            or ".." in Path(path).parts
            for path in dirty_paths
        )
    ):
        raise RunIdentityError(
            "run_identity.source.dirty_paths must be sorted unique repository-relative paths"
        )
    diff_sha256 = source.get("diff_sha256")
    if diff_sha256 is not None and (
        not isinstance(diff_sha256, str) or not SHA256_RE.fullmatch(diff_sha256)
    ):
        raise RunIdentityError("run_identity.source.diff_sha256 must be null or SHA-256")
    patch_evidence = source.get("patch_evidence")
    if patch_evidence is not None:
        if not isinstance(patch_evidence, dict):
            raise RunIdentityError("run_identity.source.patch_evidence must be an object or null")
        patch_path = patch_evidence.get("path")
        patch_hash = patch_evidence.get("sha256")
        if (
            not isinstance(patch_path, str)
            or not Path(patch_path).is_absolute()
            or ".." in Path(patch_path).parts
        ):
            raise RunIdentityError("run_identity.source.patch_evidence.path must be absolute")
        if not isinstance(patch_hash, str) or not SHA256_RE.fullmatch(patch_hash):
            raise RunIdentityError("run_identity.source.patch_evidence.sha256 must be SHA-256")
    evidence_count = int(diff_sha256 is not None) + int(patch_evidence is not None)
    if dirty and (not dirty_paths or evidence_count != 1):
        raise RunIdentityError(
            "dirty run identity requires dirty_paths and exactly one diff or patch evidence"
        )
    if not dirty and (dirty_paths or evidence_count):
        raise RunIdentityError("clean run identity cannot contain dirty evidence")

    training = identity.get("training")
    if not isinstance(training, dict):
        raise RunIdentityError("run_identity.training must be an object")
    _validate_string_array("run_identity.training.command", training.get("command"), nonempty=True)
    _validate_string_array(
        "run_identity.training.hydra_overrides",
        training.get("hydra_overrides"),
        nonempty=False,
    )
    command_iterator = iter(training["command"])
    if not all(any(token == override for token in command_iterator) for override in training["hydra_overrides"]):
        raise RunIdentityError(
            "run_identity Hydra overrides must appear in command order"
        )

    config_files = identity.get("config_files")
    if not isinstance(config_files, list) or not config_files:
        raise RunIdentityError("run_identity.config_files must be a non-empty array")
    config_paths: list[str] = []
    for entry in config_files:
        if not isinstance(entry, dict):
            raise RunIdentityError("run_identity.config_files entries must be objects")
        path = entry.get("path")
        sha256 = entry.get("sha256")
        if (
            not isinstance(path, str)
            or not path
            or Path(path).is_absolute()
            or ".." in Path(path).parts
        ):
            raise RunIdentityError("config file paths must be repository-relative")
        if not isinstance(sha256, str) or not SHA256_RE.fullmatch(sha256):
            raise RunIdentityError("config file sha256 must be SHA-256")
        config_paths.append(path)
    if config_paths != sorted(set(config_paths)):
        raise RunIdentityError("config file paths must be sorted and unique")

    if identity["version"] == 1:
        evaluation = identity.get("evaluation_scenario")
        if not isinstance(evaluation, dict):
            raise RunIdentityError("run_identity.evaluation_scenario must be an object")
        contract = evaluation.get("contract")
        validate_scenario_contract(contract)
        scenario_hash = evaluation.get("sha256")
        expected_scenario_hash = _sha256_bytes(_canonical_json(contract).encode("utf-8"))
        if scenario_hash != expected_scenario_hash:
            raise RunIdentityError("run_identity evaluation scenario SHA-256 mismatch")

    elif "evaluation_scenario" in identity:
        raise RunIdentityError("training context must not embed a scenario")

    identity_hash = identity.get("identity_sha256")
    payload = {key: value for key, value in identity.items() if key != "identity_sha256"}
    expected_identity_hash = _sha256_bytes(_canonical_json(payload).encode("utf-8"))
    if identity_hash != expected_identity_hash:
        raise RunIdentityError("run_identity identity_sha256 mismatch")


def capture_run_identity(
    repo_root: Path,
    *,
    task: str,
    run_id: str,
    host_id: str,
    backend: str,
    algorithm: str,
    runner: str,
    seed: int,
    training_command: list[str],
    hydra_overrides: list[str],
    config_paths: list[str],
    scenario_contract: dict[str, Any] | None = None,
    patch_evidence_path: Path | None = None,
) -> dict[str, Any]:
    """Capture a host-local identity using only read-only Git queries."""
    for name, value in (
        ("task", task),
        ("run-id", run_id),
        ("host-id", host_id),
        ("backend", backend),
        ("algorithm", algorithm),
        ("runner", runner),
    ):
        _validate_identifier(name, value)
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise RunIdentityError("seed must be an integer")
    _validate_string_array("training command", training_command, nonempty=True)
    _validate_string_array("Hydra overrides", hydra_overrides, nonempty=False)
    command_iterator = iter(training_command)
    if not all(any(token == override for token in command_iterator) for override in hydra_overrides):
        raise RunIdentityError("Hydra overrides must appear in training command order")
    if scenario_contract is not None:
        validate_scenario_contract(scenario_contract)
    if not config_paths:
        raise RunIdentityError("at least one --config is required")

    _reject_symlink_components(repo_root, label="repository root")
    if not repo_root.is_dir():
        raise RunIdentityError("repository root must be an existing non-symlinked absolute directory")
    discovered_root = Path(
        _git_text(repo_root, "rev-parse", "--show-toplevel").strip()
    ).resolve()
    if discovered_root != repo_root:
        raise RunIdentityError(
            f"repository root mismatch: expected {repo_root}, Git reported {discovered_root}"
        )
    branch = _git_text(
        repo_root,
        "symbolic-ref",
        "--quiet",
        "--short",
        "HEAD",
        allow_failure=True,
    ).strip() or "DETACHED"
    head = _git_text(repo_root, "rev-parse", "HEAD").strip()
    if not HEAD_RE.fullmatch(head):
        raise RunIdentityError("Git HEAD is not a full lowercase commit")

    resolved_configs: list[tuple[Path, str]] = []
    for raw_path in config_paths:
        resolved_configs.append(_repository_file(repo_root, raw_path))
    resolved_configs.sort(key=lambda item: item[1])
    relative_paths = [relative for _, relative in resolved_configs]
    if len(relative_paths) != len(set(relative_paths)):
        raise RunIdentityError("--config paths must be unique")

    dirty_paths, untracked_paths = _inspect_config_state(
        repo_root,
        resolved_configs,
    )
    dirty = bool(dirty_paths)

    diff_sha256: str | None = None
    patch_evidence: dict[str, str] | None = None
    if dirty:
        if patch_evidence_path is not None:
            patch_path = _safe_absolute_file(
                patch_evidence_path,
                label="patch evidence",
            )
            expected_patch_parent = (
                repo_root
                / "learnings"
                / "policy_tuning"
                / task
                / run_id
                / "evidence"
                / "source"
            )
            if patch_path.parent != expected_patch_parent or patch_path.suffix != ".patch":
                raise RunIdentityError(
                    "patch evidence must be a .patch file in this run's evidence/source directory"
                )
            patch_bytes = patch_path.read_bytes()
            missing_patch_paths = [
                relative
                for relative in dirty_paths
                if relative.encode("utf-8") not in patch_bytes
            ]
            if missing_patch_paths:
                raise RunIdentityError(
                    "patch evidence does not name dirty path(s): "
                    + ", ".join(missing_patch_paths)
                )
            patch_evidence = {
                "path": str(patch_path),
                "sha256": _sha256_bytes(patch_bytes),
            }
        elif untracked_paths:
            raise RunIdentityError(
                "dirty untracked config requires --patch-evidence: "
                + ", ".join(untracked_paths)
            )
        else:
            diff = _git_bytes(
                repo_root,
                "diff",
                "--no-ext-diff",
                "--no-textconv",
                "--binary",
                "--full-index",
                "HEAD",
                "--",
                *relative_paths,
            )
            if not diff:
                raise RunIdentityError(
                    "dirty tracked config produced no diff; provide --patch-evidence"
                )
            assert isinstance(diff, bytes)
            diff_sha256 = _sha256_bytes(diff)
    elif patch_evidence_path is not None:
        raise RunIdentityError("clean source cannot use --patch-evidence")

    configs = sorted(
        (
            {"path": relative, "sha256": _sha256_file(path)}
            for path, relative in resolved_configs
        ),
        key=lambda item: item["path"],
    )
    final_branch = _git_text(
        repo_root,
        "symbolic-ref",
        "--quiet",
        "--short",
        "HEAD",
        allow_failure=True,
    ).strip() or "DETACHED"
    final_head = _git_text(repo_root, "rev-parse", "HEAD").strip()
    final_dirty_paths, final_untracked_paths = _inspect_config_state(
        repo_root,
        resolved_configs,
    )
    final_configs = sorted(
        (
            {"path": relative, "sha256": _sha256_file(path)}
            for path, relative in resolved_configs
        ),
        key=lambda item: item["path"],
    )
    state_changed = (
        final_branch != branch
        or final_head != head
        or final_dirty_paths != dirty_paths
        or final_untracked_paths != untracked_paths
        or final_configs != configs
    )
    if diff_sha256 is not None:
        final_diff = _git_bytes(
            repo_root,
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--binary",
            "--full-index",
            "HEAD",
            "--",
            *relative_paths,
        )
        state_changed = state_changed or not isinstance(final_diff, bytes) or (
            _sha256_bytes(final_diff) != diff_sha256
        )
    if patch_evidence is not None:
        state_changed = state_changed or (
            _sha256_file(Path(patch_evidence["path"])) != patch_evidence["sha256"]
        )
    if state_changed:
        raise RunIdentityError("repository source changed during identity capture")
    scenario_hash = _sha256_bytes(
        _canonical_json(scenario_contract).encode("utf-8")
    )
    identity: dict[str, Any] = {
        "version": 1,
        "task": task,
        "run_id": run_id,
        "host_id": host_id,
        "backend": backend,
        "algorithm": algorithm,
        "runner": runner,
        "seed": seed,
        "source": {
            "repository_root": str(repo_root),
            "branch": branch,
            "head": head,
            "dirty": dirty,
            "dirty_paths": dirty_paths,
            "diff_sha256": diff_sha256,
            "patch_evidence": patch_evidence,
        },
        "training": {
            "command": training_command,
            "hydra_overrides": hydra_overrides,
        },
        "config_files": configs,
        "evaluation_scenario": {
            "contract": scenario_contract,
            "sha256": scenario_hash,
        },
    }
    if scenario_contract is None:
        identity["version"] = 2
        del identity["evaluation_scenario"]
    identity["identity_sha256"] = _sha256_bytes(
        _canonical_json(identity).encode("utf-8")
    )
    validate_run_identity(identity)
    return identity


def write_new_absolute_output(path: Path, encoded: str) -> None:
    if not path.is_absolute():
        raise RunIdentityError("--output must be a new absolute path")
    _reject_symlink_components(path.parent, label="--output")
    if not path.parent.is_dir():
        raise RunIdentityError("--output parent directory does not exist")
    if path.exists() or path.is_symlink():
        raise RunIdentityError("--output already exists")
    try:
        with path.open("x", encoding="utf-8") as stream:
            stream.write(encoded)
    except FileExistsError as exc:
        raise RunIdentityError("--output already exists") from exc


def _parse_json_argument(parser: argparse.ArgumentParser, name: str, raw: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        parser.error(f"{name} is invalid JSON at column {exc.colno}: {exc.msg}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--task", required=True)
    parser.add_argument("--run-id", required=True)
    parser.add_argument("--host-id", required=True)
    parser.add_argument("--backend", required=True)
    parser.add_argument("--algorithm", required=True)
    parser.add_argument("--runner", required=True)
    parser.add_argument("--seed", required=True, type=int)
    parser.add_argument("--training-command-json", required=True)
    parser.add_argument("--hydra-overrides-json", default="[]")
    parser.add_argument("--config", action="append", default=[])
    parser.add_argument("--scenario-contract-json", help="Legacy v1 only; omit for reusable v2 context")
    parser.add_argument("--patch-evidence")
    parser.add_argument("--repo-root", default=str(REPO_ROOT))
    parser.add_argument("--output", help="New legacy identity path; v2 uses content-addressed storage")
    args = parser.parse_args()
    training_command = _parse_json_argument(
        parser,
        "--training-command-json",
        args.training_command_json,
    )
    hydra_overrides = _parse_json_argument(
        parser,
        "--hydra-overrides-json",
        args.hydra_overrides_json,
    )
    scenario_contract = _parse_json_argument(
        parser,
        "--scenario-contract-json",
        args.scenario_contract_json,
    ) if args.scenario_contract_json is not None else None
    try:
        identity = capture_run_identity(
            Path(args.repo_root),
            task=args.task,
            run_id=args.run_id,
            host_id=args.host_id,
            backend=args.backend,
            algorithm=args.algorithm,
            runner=args.runner,
            seed=args.seed,
            training_command=training_command,
            hydra_overrides=hydra_overrides,
            config_paths=args.config,
            scenario_contract=scenario_contract,
            patch_evidence_path=(
                Path(args.patch_evidence) if args.patch_evidence else None
            ),
        )
        encoded = json.dumps(
            identity,
            indent=2,
            sort_keys=True,
            ensure_ascii=False,
            allow_nan=False,
        ) + "\n"
        if identity["version"] == 2:
            from evidence_provenance import store_object, run_root
            if args.output:
                raise RunIdentityError("v2 context chooses its content-addressed output; omit --output")
            print(json.dumps(store_object(run_root(identity), "context", identity)))
        else:
            if not args.output:
                raise RunIdentityError("legacy identity requires --output")
            write_new_absolute_output(Path(args.output), encoded)
    except (OSError, RunIdentityError) as exc:
        parser.error(str(exc))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Shared, versioned provenance paths and immutable content-addressed objects.

No simulator imports. Historical validation checks captured content; preflight
additionally checks the live evaluator sources. The mutable index is not evidence.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import subprocess
import tempfile
from pathlib import Path


def safe_path(path: Path) -> None:
    if not path.is_absolute() or ".." in path.parts:
        raise ValueError("path must be absolute without traversal")
    for part in (path, *path.parents):
        if part.is_symlink():
            raise ValueError(f"symlinked path: {part}")


def identifier(value: str) -> str:
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}", value):
        raise ValueError("unsafe identifier")
    return value


def encode(value: dict) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False, allow_nan=False) + "\n").encode()


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def read_reference(reference: dict) -> dict:
    if not isinstance(reference, dict) or set(reference) != {"path", "sha256"}:
        raise ValueError("reference must contain path and sha256")
    path = Path(reference["path"])
    safe_path(path)
    data = path.read_bytes()
    if digest(data) != reference["sha256"]:
        raise ValueError(f"reference SHA-256 mismatch: {path}")
    value = json.loads(data)
    if not isinstance(value, dict):
        raise ValueError("reference must contain a JSON object")
    return value


def write_bytes(path: Path, data: bytes, *, reuse: bool = False, replace_index: bool = False) -> dict:
    safe_path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    safe_path(path)
    if replace_index and path.name != "index.md":
        raise ValueError("only index.md may be replaced")
    # Private same-filesystem temporary + exclusive link; readers see whole files.
    with tempfile.TemporaryDirectory(prefix=".publish-", dir=path.parent) as temporary:
        source = Path(temporary) / "content"
        with source.open("xb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        if replace_index:
            safe_path(path)
            os.replace(source, path)
        else:
            try:
                os.link(source, path, follow_symlinks=False)
            except FileExistsError:
                safe_path(path)
                if not reuse or not path.is_file() or path.read_bytes() != data:
                    raise ValueError(f"evidence already exists or differs: {path}")
    return {"path": str(path), "sha256": digest(data)}


def run_root(identity: dict) -> Path:
    return (Path(identity["source"]["repository_root"]) / "learnings" / "policy_tuning"
            / identifier(identity["task"]) / identifier(identity["run_id"]))


def store_object(root: Path, kind: str, value: dict) -> dict:
    if kind not in {"context", "config", "scenario", "source"}:
        raise ValueError("unsupported provenance kind")
    data = encode(value)
    path = root / "provenance" / f"{kind}-{digest(data)}.json"
    return write_bytes(path, data, reuse=True)


def require_source_path(path: Path, root: Path, kind: str) -> None:
    """Select old/new layout by the artifact's explicit schema, never by fallback."""
    safe_path(path)
    try:
        data = path.read_bytes()
        value = json.loads(data)
    except (OSError, ValueError) as exc:
        raise ValueError(f"cannot read source evidence: {path}") from exc
    if not isinstance(value, dict):
        raise ValueError("source evidence must be an object")
    if value.get("version") == 2 and kind in {"context", "config"}:
        expected = root / "provenance" / f"{kind}-{digest(path.read_bytes())}.json"
        if path != expected:
            raise ValueError("content-addressed provenance path mismatch")
    elif value.get("version") == 1 and kind in {"context", "config"}:
        prefix = "identity" if kind == "context" else "effective-config"
        if path.parent != root / "evidence" / "source" or not re.fullmatch(
            prefix + r"-[A-Za-z0-9][A-Za-z0-9._-]{0,127}\.json", path.name
        ):
            raise ValueError("legacy source evidence layout mismatch")
    else:
        raise ValueError("unsupported provenance schema")


def require_object(reference: dict, root: Path, kind: str) -> dict:
    value = read_reference(reference)
    if Path(reference["path"]) != root / "provenance" / f"{kind}-{reference['sha256']}.json":
        raise ValueError("provenance reference outside the current run")
    return value


def capture_evaluator_source(root: Path, repo: Path, files: list[Path]) -> dict:
    """Preserve exact source bytes once, including authorized untracked helpers."""
    safe_path(repo)
    before = subprocess.check_output(["git", "-C", str(repo), "rev-parse", "HEAD"], text=True).strip()
    captured = []
    for path in sorted(set(files)):
        safe_path(path)
        relative = str(path.relative_to(repo))
        data = path.read_bytes()
        captured.append({"path": relative, "sha256": digest(data), "content_utf8": data.decode("utf-8")})
    after = subprocess.check_output(["git", "-C", str(repo), "rev-parse", "HEAD"], text=True).strip()
    if before != after or any(digest((repo / f["path"]).read_bytes()) != f["sha256"] for f in captured):
        raise ValueError("evaluator source changed during capture")
    return store_object(root, "source", {"version": 1, "repository_root": str(repo), "head": before, "files": captured})


def capture_scenario(identity: dict, contract: dict, source: dict) -> dict:
    from capture_run_identity import validate_scenario_contract
    validate_scenario_contract(contract)
    if contract["seed"] != identity["seed"]:
        raise ValueError("scenario seed mismatch")
    return store_object(run_root(identity), "scenario", {
        "version": 1, "task": identity["task"], "run_id": identity["run_id"],
        "contract": contract, "evaluator_source": source,
    })


def validate_provenance(identity: dict, config_ref: dict, scenario_ref: dict, contract: dict, *, live: bool = False) -> None:
    from capture_effective_training_config import load_and_validate_effective_config
    from capture_run_identity import validate_run_identity
    validate_run_identity(identity)
    if identity["version"] != 2:
        raise ValueError("batch evaluations require training context version 2")
    root = run_root(identity)
    config = require_object(config_ref, root, "config")
    if config.get("version") != 2:
        raise ValueError("batch evaluations require config version 2")
    load_and_validate_effective_config(Path(config_ref["path"]), expected_sha256=config_ref["sha256"], run_identity=identity)
    scenario = require_object(scenario_ref, root, "scenario")
    if set(scenario) != {"version", "task", "run_id", "contract", "evaluator_source"} or scenario["version"] != 1:
        raise ValueError("invalid scenario evidence")
    if scenario["contract"] != contract or any(scenario[f] != identity[f] for f in ("task", "run_id")):
        raise ValueError("scenario evidence scope or contract mismatch")
    source = require_object(scenario["evaluator_source"], root, "source")
    if source.get("version") != 1 or source.get("repository_root") != identity["source"]["repository_root"]:
        raise ValueError("evaluator source scope mismatch")
    if not re.fullmatch(r"[0-9a-f]{40}", source.get("head", "")) or not source.get("files"):
        raise ValueError("evaluator source missing")
    seen = set()
    for entry in source["files"]:
        relative = Path(entry["path"])
        if relative.is_absolute() or ".." in relative.parts or str(relative) in seen:
            raise ValueError("unsafe or duplicate evaluator source")
        seen.add(str(relative))
        if digest(entry["content_utf8"].encode("utf-8")) != entry["sha256"]:
            raise ValueError("captured evaluator source SHA-256 mismatch")
        if live:
            path = Path(source["repository_root"]) / relative
            safe_path(path)
            if digest(path.read_bytes()) != entry["sha256"]:
                raise ValueError(f"live evaluator source drift: {relative}")
    if live:
        required = {
            "scripts/reinforcement_learning/rsl_rl/evaluate_policy.py",
            "scripts/reinforcement_learning/rsl_rl/policy_evaluation_evidence.py",
            "scripts/reinforcement_learning/rsl_rl/policy_evaluation_telemetry.py",
            ".agents/skills/monitor-tune-isaaclab-training/scripts/evidence_provenance.py",
        }
        if not required <= seen:
            raise ValueError("missing required evaluator source files")

